pm.test('a reset request for a registered address is accepted', function () {
  pm.expect(pm.response.code).to.equal(200);
});

pm.test('a reset request with no email is rejected and names the email field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body).to.have.property('email');
});

pm.test('reset request response shape: HTTP 200 (captured here for comparison against the unregistered-address request)', function () {
  pm.expect(pm.response.code).to.equal(200);
  pm.collectionVariables.set('resetRegisteredStatus', pm.response.code);
  pm.collectionVariables.set('resetRegisteredBody', pm.response.text());
});

pm.test('a reset request for an unregistered address is answered identically to one for a registered address', function () {
  const registeredStatus = pm.collectionVariables.get('resetRegisteredStatus');
  const registeredBody = pm.collectionVariables.get('resetRegisteredBody');
  pm.expect(pm.response.code, 'status should match the registered-address request').to.equal(registeredStatus);
  pm.expect(pm.response.text(), 'body should match the registered-address request').to.equal(registeredBody);
});

pm.test('a reset request response never contains a code or a link', function () {
  const text = pm.response.text();
  pm.expect(text, 'response should not contain an absolute link').to.not.match(/https?:\/\//);
  pm.expect(text, 'response should not contain a \'code\' or \'link\' key').to.not.match(/"(code|link|reset_link)"\s*:/);
});

pm.test('the 6th reset request for one address within the run is refused with the fixed 429 body and no retry-time header', function () {
  pm.expect(pm.response.code, 'expected the per-address limit (5/hour) to have been reached').to.equal(429);
  const body = pm.response.json();
  pm.expect(body).to.eql({ detail: 'Too many reset requests for that address. Try again later.' });
  pm.expect(pm.response.headers.has('Retry-After'), 'response should not carry a Retry-After header').to.be.false;
});
